import { capconsDataProps, stripCapconsProps, type CapconsBaseProps, type CapconsBasePropsLoose } from "@capcons/sdk/components";

/**
 * Split CapCons authoring props from a React prop bag: remove JSX-only keys and append `data-capcons-*`
 * attributes suitable for the **root** DOM node of a primitive (Radix slot, intrinsic element, etc.).
 *
 * Typed as `any` on purpose so Radix/shadcn **discriminated unions** on the caller survive `Omit`/`Pick`
 * (e.g. Accordion vs ToggleGroup variants). The returned object is still `{ ...hostProps, ...dataAttrs }`.
 *
 * @param source - Component props that intersect {@link CapconsBasePropsLoose} with the host component.
 * @returns A spreadable object: non-CapCons props plus serialized `data-capcons-*` entries.
 *
 * @example Button as section root
 * ```tsx
 * function Button(p: React.ComponentProps<'button'> & CapconsBasePropsLoose) {
 *   return <button type="button" {...capconsSpread(p)} />;
 * }
 *
 * <Button section sectionLabel="Hero" capconsCapabilities="duplicate,delete">Save</Button>
 * ```
 */
export function capconsSpread<P extends CapconsBasePropsLoose & Record<string, unknown>>(source: P) {
  const c = source;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- preserve caller unions for JSX spreads
  return { ...stripCapconsProps(c), ...capconsDataProps(c) } as any;
}

export type { CapconsBaseProps, CapconsBasePropsLoose };

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import * as React from "react"

const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener("change", onChange)
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return !!isMobile
}
